                    corner(vc, m, b.add(k), cb);
                    corner(vc, m, b.subtract(k), cb);
                    corner(vc, m, b.subtract(k), cb);
                    corner(vc, m, b.add(k), cb);
                    corner(vc, m, a.add(k), ca);
                    corner(vc, m, a.subtract(k), ca);
